def check(call, data, today):
    # Only relevant for Freshdesk ticket creation
    if call.get("tool") != "freshdesk_create_ticket":
        return []
    args = call.get("args", {})
    # Find the Freshdesk priority rule for tag 'urgent'
    expected = None
    for rec in records(data):
        # Look for rows from the ws_priority_rules sheet (they contain the keys we need)
        if "Tag" in rec and "Freshdesk Priority" in rec:
            if norm(rec["Tag"]) == "urgent":
                expected = num(rec["Freshdesk Priority"])  # may be None if not a number
                break
    # If we have no rule, we cannot decide
    if expected is None:
        return []
    # The policy only applies when the ticket is tagged 'urgent'.
    # The create call does not expose tags, so we cannot know; assume no violation.
    # If the call explicitly provides a tag field, enforce the mapping.
    tags = args.get("tags") or []
    # tags may be a list or a comma‑separated string
    if isinstance(tags, str):
        tags = [t.strip() for t in tags.split(",")]
    if any(norm(t) == "urgent" for t in tags):
        # Ticket is marked urgent – check priority
        call_pri = num(args.get("priority"))
        if call_pri is None:
            return []
        if call_pri != expected:
            return [f"Ticket with urgent tag has priority {call_pri}, expected {int(expected)}"]
    return []

def check(call, data, today):
    # Only relevant for freshdesk_create_ticket calls
    if call.get("tool") != "freshdesk_create_ticket":
        return []
    args = call.get("args", {})
    # Tags may be supplied directly; if not present we cannot decide
    tags = args.get("tags") or []
    if not isinstance(tags, list):
        # sometimes tags could be a comma‑separated string
        tags = [t.strip() for t in str(tags).split(",") if t.strip()]
    if not tags:
        return []
    priority = args.get("priority")
    violations = []
    for tag in tags:
        if norm(tag) == "high-priority":
            if priority != 3:
                violations.append("Ticket with tag high-priority must have priority 3")
    return violations

def check(call, data, today):
    # Only relevant for Freshdesk ticket creation
    if call.get('tool') != 'freshdesk_create_ticket':
        return []
    args = call.get('args', {})
    # Priority supplied in the call
    priority = args.get('priority')
    # Tags may be supplied directly or embedded in free‑text fields (subject/description)
    tags = []
    if isinstance(args.get('tags'), (list, tuple)):
        tags = [norm(t) for t in args.get('tags') if isinstance(t, str)]
    # also look for tag words in subject/description (simple split on non‑alphanum)
    for field in ('subject', 'description'):
        txt = args.get(field)
        if isinstance(txt, str):
            tags.extend([norm(tok) for tok in re.split(r"[^A-Za-z0-9_-]+", txt) if tok])
    tags = set(tags)

    # Find the priority rule for tag "default" from the spreadsheet records
    priority_rules = []
    for rec in records(data):
        if rec.get('Tag') and rec.get('Freshdesk Priority'):
            priority_rules.append(rec)
    expected = None
    for r in priority_rules:
        if norm(r['Tag']) == 'default':
            expected = int(num(r['Freshdesk Priority']))
            break
    # If no rule for "default" is present, we cannot decide
    if expected is None:
        return []

    # If the ticket does not carry the "default" tag, the rule does not apply
    if 'default' not in tags:
        return []

    # At this point the ticket has the default tag – enforce the priority mapping
    if priority is None:
        return ["Ticket with tag 'default' missing priority field"]
    try:
        pr_val = int(num(priority))
    except Exception:
        return ["Ticket with tag 'default' has non‑numeric priority"]
    if pr_val != expected:
        return [f"Ticket with tag 'default' must have priority {expected}, got {pr_val}"]
    return []

def check(call, data, today):
    # Only applies to Slack alerts defined in notification rules
    if call.get('tool') != 'slack_send_channel_message':
        return []
    # Gather all notification rule records (worksheet ws_notification_rules)
    notif_records = []
    for rec in records(data, tool='google_sheets_find_many_rows'):
        # the sheet name is not stored, but the worksheet_id matches ws_notification_rules in the sample
        # we rely on the presence of the expected columns to identify the rule sheet
        if {'Alert_Level', 'Salesforce_Task', 'Email_AE', 'Slack_Alert'}.issubset(rec.keys()):
            notif_records.append(rec)
    if not notif_records:
        return []
    violations = []
    for r in notif_records:
        if norm(r.get('Alert_Level', '')) != 'critical':
            continue
        slack_flag = norm(r.get('Slack_Alert', ''))
        # If the rule says a Slack alert is required but the call is not a Slack send, flag it
        if slack_flag == 'yes' and call.get('tool') != 'slack_send_channel_message':
            rec_id = r.get('id') or r.get('row_id') or 'unknown'
            violations.append(f"Record {rec_id}: Slack_Alert required but call is not Slack")
    return violations

def check(call, data, today):
    # Only relevant for Slack messages
    if call.get('tool') != 'slack_send_channel_message':
        return []

    # Gather notification rule rows from the sheet "ws_notification_rules"
    notif_rows = []
    for entry in data:
        if entry.get('tool') == 'google_sheets_find_many_rows' and entry.get('args', {}).get('worksheet') == 'ws_notification_rules':
            notif_rows.extend(entry.get('records', []))

    # If we have no notification‑rule records, we cannot decide
    if not notif_rows:
        return []

    violations = []
    for rec in notif_rows:
        if norm(rec.get('Alert_Level', '')) != 'info':
            continue
        # Expected values for an "info" alert
        sf_task = norm(rec.get('Salesforce_Task', ''))
        email_ae = norm(rec.get('Email_AE', ''))
        slack_alert = norm(rec.get('Slack_Alert', ''))
        # Check each condition
        if sf_task != 'no' or email_ae != 'no' or slack_alert != 'yes':
            rec_id = rec.get('id') or rec.get('row_id') or 'unknown'
            violations.append(f"Record {rec_id} violates info‑level notification rule.")
    return violations

def check(call, data, today):
    # Only relevant for email sending actions
    if call.get('tool') != 'gmail_send_email':
        return []
    # Gather all sheet rows that may contain notification rules
    rows = []
    for rec in records(data):
        # rows from the notification_rules worksheet have the expected keys
        if 'Alert_Level' in rec and 'Email_AE' in rec:
            rows.append(rec)
    # If we cannot find any rule, we cannot decide
    if not rows:
        return []
    violations = []
    for r in rows:
        if norm(r.get('Alert_Level')) != 'info':
            continue
        # According to the policy, when Alert_Level is info, Email_AE must be "yes"
        email_ae = norm(r.get('Email_AE'))
        if email_ae == 'no':
            # The planned call sends an email, which violates the rule
            rec_id = r.get('id') or r.get('row_id') or 'unknown'
            violations.append(f"Record {rec_id} (info) disallows Email_AE but gmail_send_email is called")
        # Optionally, we could also check Salesforce_Task and Slack_Alert, but they do not affect the email action
    return violations
